INSERT INTO `es_events` VALUES ('58ed5f1c-568e-4dea-a91e-3dd3ccc8a5f0','1ST CSIT Student Congress 2026','Dynamic scoring rubric based on paper presentation criteria.',NULL,'standard','[{\"score\":4,\"label\":\"Excellent\"},{\"score\":3,\"label\":\"Exceeds Expectations\"},{\"score\":2,\"label\":\"Meets Expectations\"},{\"score\":1,\"label\":\"Meets Expectations Sometimes\"},{\"score\":0,\"label\":\"Does Not Meet Expectations\"}]',NULL,'2026-05-07 23:14:20.367'),('79b39904-bd68-4762-b5d6-9d7c3d4a1cd3','CSC 205 - DIORAMA','Computer Architecture and Organization Finals','Rosette','standard','[{\"score\":4,\"label\":\"Excellent\"},{\"score\":3,\"label\":\"Exceeds Expectations\"},{\"score\":2,\"label\":\"Meets Expectations\"},{\"score\":1,\"label\":\"Meets Expectations Sometimes\"},{\"score\":0,\"label\":\"Does Not Meet Expectations\"}]',NULL,'2026-05-19 08:28:09.313'),('85844889-3ab7-4ad1-a125-b05f061af880','ITS 405 MULTIMEDIA FILM SHOWING',NULL,NULL,'standard','[{\"score\":4,\"label\":\"Excellent\"},{\"score\":3,\"label\":\"Exceeds Expectations\"},{\"score\":2,\"label\":\"Meets Expectations\"},{\"score\":1,\"label\":\"Meets Expectations Sometimes\"},{\"score\":0,\"label\":\"Does Not Meet Expectations\"}]',NULL,'2026-05-13 10:29:43.500'),('9dd2f20a-270a-4f2d-a1f9-09e7e4a07e59','Final Oral Defense','Group and individual presentation scoring for final oral defense.',NULL,'final-oral-defense','[{\"score\":4,\"label\":\"Excellent\"},{\"score\":3,\"label\":\"Exceeds Expectations\"},{\"score\":2,\"label\":\"Meets Expectations\"},{\"score\":1,\"label\":\"Meets Expectations Sometimes\"},{\"score\":0,\"label\":\"Does Not Meet Expectations\"}]',NULL,'2026-05-12 02:23:23.793'),('dcbf05b1-b2e4-4b28-b12d-681b0952867a','ITS 208 FINAL PROJECT',NULL,NULL,'standard','[{\"score\":0,\"label\":\"Does Not Meet Expectations\"}]',NULL,'2026-05-21 09:03:26.120'),('ea19b3f0-2213-4789-89ae-98565d894ac2','Database Management System 2 Final Project (2026)','Students will design and implement a DBMS-driven information system. The project must demonstrate mastery of database design, SQL queries, relational algebra translation, and system development in any programming language or framework (Java, Python, PHP/Laravel, C#, etc.).','Christian Franc Carvajal','standard','[{\"score\":4,\"label\":\"Excellent\"},{\"score\":3,\"label\":\"Exceeds Expectations\"},{\"score\":2,\"label\":\"Meets Expectations\"},{\"score\":1,\"label\":\"Meets Expectations Sometimes\"},{\"score\":0,\"label\":\"Does Not Meet Expectations\"}]',NULL,'2026-05-14 05:54:12.507'),('eda2dd29-bf06-4bb3-8a36-5385b74fe61e','1ST CSIT Poster Presentation 2026',NULL,NULL,'standard','[{\"score\":4,\"label\":\"Excellent\"},{\"score\":3,\"label\":\"Exceeds Expectations\"},{\"score\":2,\"label\":\"Meets Expectations\"},{\"score\":1,\"label\":\"Meets Expectations Sometimes\"},{\"score\":0,\"label\":\"Does Not Meet Expectations\"}]',NULL,'2026-05-08 02:17:33.349');
